       "Atomic mass unit: 1 u = 1.6605×10⁻²⁷ kg — one-twelfth the mass of a carbon-12 atom.",
       "Caesium atomic clock is the most accurate time standard: 9,192,631,770 vibrations of Cs-133 = 1 second.",
       "In 2019 the SI was redefined — the 7 base units are now defined via 7 fundamental constants (Planck constant h, elementary charge e, Boltzmann constant k, Avogadro constant N_A, etc.).",
       "Useful dimensions: impulse [MLT⁻¹]; angular momentum and Planck constant [ML²T⁻¹]; coefficient of viscosity [ML⁻¹T⁻¹]; spring/force constant k [MT⁻²]; gravitational constant G [M⁻¹L³T⁻²].",
       "Combination of errors: absolute errors add in sum/difference (ΔZ = ΔA + ΔB); relative (percentage) errors add in multiplication/division (ΔZ/Z = ΔA/A + ΔB/B).",
       "Accuracy = closeness of measured value to the true value; precision = closeness of repeated measurements to each other — they are different qualities.",
       "SI prefixes: tera 10¹², giga 10⁹, mega 10⁶, kilo 10³, milli 10⁻³, micro 10⁻⁶, nano 10⁻⁹, pico 10⁻¹², femto 10⁻¹⁵.",
