       "In circular motion centripetal force is real (toward centre); centrifugal force is a pseudo force felt in the rotating frame — an effect of inertia.",
       "Angular quantities: angular displacement θ, angular velocity ω = dθ/dt, angular acceleration α = dω/dt; linear relations: v = ωr, a_t = αr, a_c = ω²r.",
